#include <bits/stdc++.h>
using namespace std;

int main(){
    const int N=300;
    int B = (int)sqrt(N)+2; // > sqrt N
    // spf
    vector<int> spf(N+1);
    for(int i=0;i<=N;i++) spf[i]=i;
    for(int i=2;i*i<=N;i++) if(spf[i]==i) for(int j=i*i;j<=N;j+=i) if(spf[j]==j) spf[j]=i;
    int M = N/2 + 5;
    int W = M/64 + 2;
    vector<vector<unsigned long long>> seen(N+1, vector<unsigned long long>(W,0)); // only small primes used
    vector<vector<int>> vals(N+1);
    vector<int> g(N+1,0);
    for(int n=1;n<=N;n++){
        if(n%2==0){
            g[n]=n/2-1;
        } else {
            // distinct factors
            vector<int> small, large;
            int t=n;
            while(t>1){
                int p=spf[t];
                if(p <= B) small.push_back(p); else large.push_back(p);
                while(t%p==0) t/=p;
            }
            if(n==1) { g[n]=0; }
            else {
                vector<unsigned long long> extra(W,0);
                if(!large.empty()){
                    int q=large[0];
                    for(int v: vals[q]) extra[v>>6] |= 1ULL<<(v&63);
                }
                int got=-1;
                for(int w=0; w<W; w++){
                    unsigned long long val=0;
                    for(int p: small) val |= seen[p][w];
                    if(!large.empty()) val |= extra[w];
                    if(val != ~0ULL){
                        int bit=__builtin_ctzll(~val);
                        got = w*64 + bit;
                        break;
                    }
                }
                if(got<0){ cerr<<"M too small\n"; exit(1); }
                g[n]=got;
            }
        }
        // update
        int t=n;
        while(t>1){
            int p=spf[t];
            if(p <= B) seen[p][g[n]>>6] |= 1ULL<<(g[n]&63);
            else vals[p].push_back(g[n]);
            while(t%p==0) t/=p;
        }
    }
    // naive
    vector<int> naive(N+1,0);
    for(int x=1;x<=N;x++){
        vector<char> vis(N+5,0);
        for(int y=1;y<x;y++) if(std::gcd(x,y)>1) vis[naive[y]]=1;
        int m=0; while(vis[m]) m++;
        naive[x]=m;
    }
    for(int i=1;i<=N;i++){
        if(g[i]!=naive[i]) cout<<"Mismatch "<<i<<" g="<<g[i]<<" naive="<<naive[i]<<"\n";
    }
    cout<<"Done, B="<<B<<" W="<<W<<"\n";
    for(int i=1;i<=50;i++) cout<<i<<":"<<g[i]<<" ";
    cout<<"\n";
    return 0;
}

